   [146]={next_id=147, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="当然。有时候，一点点笨拙和紧张，反而更显珍贵。", msg_color="", msg_size=0, talker="蒂雅", audio="", img="arts/ui/bg/story/storybg_901.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4518", 0, 0, 12, 206},{ 3, "4509", 0, 0, 3, 215.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [147]={next_id=148, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="重要的是——“传达”这份心意的愿望。", msg_color="", msg_size=0, talker="蒂雅", audio="", img="arts/ui/bg/story/storybg_901.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4518", 0, 0, 12, 206},{ 3, "4509", 0, 0, 3, 215.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
